namespace Inventory;

/// <summary>
/// Runs cycle counts, reconciles discrepancies and updates valuations.
/// </summary>
public sealed class CycleCountService
{
    private readonly CycleCountOperations _operations = new();

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _operations.RecordCount(item, warehouse, counted);

    public int CountVariance(StockItem item) =>
        _operations.CountVariance(item);

    public string Reconcile(StockItem item) =>
        _operations.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _operations.FlagDiscrepancy(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _operations.UpdateValuation(item, unitCost);
}

internal sealed class CycleCountOperations
{
    private readonly ValuationLedger _valuations = new();
    private readonly CountProcessor _counts;
    private readonly DiscrepancyProcessor _discrepancies = new();
    private readonly ValuationProcessor _valuationProcessor;

    public CycleCountOperations()
    {
        _counts = new CountProcessor(_valuations);
        _valuationProcessor = new ValuationProcessor(_valuations);
    }

    public string RecordCount(StockItem item, Warehouse warehouse, int counted) =>
        _counts.Record(item, warehouse, counted);

    public int CountVariance(StockItem item) =>
        _counts.GetVariance(item);

    public string Reconcile(StockItem item) =>
        _discrepancies.Reconcile(item);

    public bool FlagDiscrepancy(StockItem item, string reason) =>
        _discrepancies.Flag(item, reason);

    public decimal UpdateValuation(StockItem item, decimal unitCost) =>
        _valuationProcessor.Update(item, unitCost);
}

internal sealed class CountProcessor
{
    private readonly Dictionary<string, int> _counts = new(StringComparer.Ordinal);
    private readonly ValuationLedger _valuations;

    public CountProcessor(ValuationLedger valuations)
    {
        _valuations = valuations;
    }

    public string Record(StockItem item, Warehouse warehouse, int counted)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";
        if (counted < 0)
            return "invalid";
        if (string.IsNullOrEmpty(warehouse.Code))
            return "no warehouse";

        _counts[item.Sku] = counted;
        var variance = counted - item.OnHand;
        if (variance == 0)
            return "match";

        _valuations.Set(item.Sku, variance > 0 ? variance * 2.0m : variance * 1.0m);
        if (variance > 100 || variance < -100)
            return "large variance";
        if (counted == 0 && item.OnHand > 0)
            return "zeroed";
        return "recorded";
    }

    public int GetVariance(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0;
        if (!_counts.TryGetValue(item.Sku, out var counted))
            return 0;

        var variance = counted - item.OnHand;
        if (variance == 0)
            return 0;
        if (variance > 1000)
            return 1000;
        if (variance < -1000)
            return -1000;
        if (variance > 0 && counted > item.OnHand * 2)
            return variance + 1;
        if (variance < 0)
            return variance;
        return variance;
    }
}

internal sealed class DiscrepancyProcessor
{
    private readonly List<string> _discrepancies = new();

    public string Reconcile(StockItem item)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return "no sku";

        int available = item.OnHand - item.Reserved;
        if (available < 0)
        {
            _discrepancies.Add($"{item.Sku}:oversold");
            return "oversold";
        }
        if (item.Reserved < 0)
        {
            _discrepancies.Add($"{item.Sku}:negative-reserve");
            return "bad reserve";
        }
        if (item.OnHand == 0 && item.Reserved > 0)
        {
            _discrepancies.Add($"{item.Sku}:phantom-reserve");
            return "phantom";
        }

        if (available > 0 && available < 5)
            _discrepancies.Add($"{item.Sku}:low");
        else if (available > 10000)
            _discrepancies.Add($"{item.Sku}:excess");

        return _discrepancies.Count > 1000
            ? "too many discrepancies"
            : "reconciled";
    }

    public bool Flag(StockItem item, string reason)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return false;
        if (string.IsNullOrEmpty(reason))
            return false;
        if (reason.Length > 200)
            reason = reason.Substring(0, 200);
        if (_discrepancies.Count > 5000)
            return false;

        string tag = Classify(reason);
        _discrepancies.Add($"{item.Sku}:{tag}:{reason}");
        if (tag == "critical" && _discrepancies.Count > 0)
            return true;
        return tag != "note";
    }

    private static string Classify(string reason)
    {
        if (reason.StartsWith("oversold", StringComparison.Ordinal))
            return "critical";
        if (reason.StartsWith("low", StringComparison.Ordinal))
            return "warn";
        if (reason.StartsWith("excess", StringComparison.Ordinal))
            return "info";
        return "note";
    }
}

internal sealed class ValuationProcessor
{
    private readonly ValuationLedger _valuations;

    public ValuationProcessor(ValuationLedger valuations)
    {
        _valuations = valuations;
    }

    public decimal Update(StockItem item, decimal unitCost)
    {
        if (string.IsNullOrEmpty(item.Sku))
            return 0m;
        if (unitCost < 0m)
            return 0m;

        int basisQuantity = item.OnHand > 0 ? item.OnHand : 0;
        decimal value = basisQuantity * unitCost;
        if (value > 1_000_000m)
            value = 1_000_000m;
        else if (value < 0m)
            value = 0m;

        _valuations.Set(item.Sku, value);
        if (basisQuantity == 0 || unitCost == 0m)
            return 0m;
        return value;
    }
}

internal sealed class ValuationLedger
{
    private readonly Dictionary<string, decimal> _values = new(StringComparer.Ordinal);

    public void Set(string sku, decimal value)
    {
        _values[sku] = value;
    }
}
